mapper.select:
SELECT c.id, c.no, c.warehouse_id, w.name AS warehouse_name, c.purpose, c.scope, c.count_date, c.counter_id,
       c.status, c.version, c.create_by, c.create_time,
       agg.item_count, agg.filled_count, agg.gain_count, agg.loss_count, cat.category_names
FROM 



    (
        SELECT mc.* FROM inv_count mc WHERE upper(mc.no) LIKE #{keywordPrefix}
        OR upper(mc.no) IN #{code}
        UNION
        SELECT mc.* FROM inv_count mc JOIN bas_warehouse mw ON mw.id = mc.warehouse_id
        WHERE mw.name ILIKE #{keywordContains}
        UNION
        SELECT mc.* FROM inv_count mc JOIN sys_user mu ON mu.id = mc.counter_id
        WHERE mu.nickname ILIKE #{keywordContains}
        UNION
        SELECT mc.* FROM inv_count_item mi JOIN inv_count mc ON mc.id = mi.count_id WHERE mi.material_sku_id IN (
            SELECT mk.id FROM bas_material_sku mk WHERE upper(mk.code) LIKE #{keywordPrefix}
            UNION
            SELECT mk.id FROM bas_material_sku mk JOIN bas_material mm ON mm.id = mk.material_id
            WHERE upper(mm.code) LIKE #{keywordPrefix} OR mm.name ILIKE #{keywordContains}
        )
    )

    inv_count
 c
JOIN bas_warehouse w ON w.id = c.warehouse_id
LEFT JOIN LATERAL (SELECT COUNT(*) AS item_count, COUNT(i.counted_qty) AS filled_count,
                          COUNT(*) FILTER (WHERE i.counted_qty > i.book_qty) AS gain_count,
                          COUNT(*) FILTER (WHERE i.counted_qty < i.book_qty) AS loss_count
                   FROM inv_count_item i WHERE i.count_id = c.id) agg ON true
LEFT JOIN LATERAL (SELECT string_agg(COALESCE(pc.name || '-', '') || mc.name, '、' ORDER BY mc.code) AS category_names
                   FROM inv_count_category cc
                   JOIN bas_material_category mc ON mc.id = cc.category_id
                   LEFT JOIN bas_material_category pc ON pc.id = mc.parent_id
                   WHERE cc.count_id = c.id) cat ON true
WHERE true
AND (c.create_by = #{scope.userId} OR c.counter_id = #{scope.userId})

    AND c.status IN #{s}

AND c.warehouse_id = #{q.warehouseId}
AND c.purpose = #{q.purpose}
AND c.count_date >= #{q.countDateFrom}
AND c.count_date <= #{q.countDateTo}

    AND c.id IN #{id}

ORDER BY c.id DESC
